// Some portions generated by Claude
// @ts-check
const { test, expect } = require('@playwright/test');
const {
    deleteRepository,
    memoryRepositoryConfiguration,
    repositoryPageUrl,
    serverBaseUrl,
    uniqueRepositoryId,
    waitForRoute
} = require('./workbench-test-helpers.js');

// The Graph page's gestures follow a few rules wherever they are made: Escape closes the topmost thing (a menu, then
// the details card with the highlight it explains, then the selection), a press outside a toolbar menu closes it, the
// node menu acts on the node it was opened on unless that node is selected, the node shown in the card is never faded,
// a selection gesture while a filter is active edits the selection on screen, hiding never re-arranges the graph or
// draws a class on its own, and looking around while a layout runs does not stop it halfway.
const REPOSITORY_ID = uniqueRepositoryId('graph-consistency');
const LARGE_REPOSITORY_ID = uniqueRepositoryId('graph-consistency-large');
const LARGE_NODES = 520;
const DATA = `
@prefix ex: <http://example.org/consistency/> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
ex:alice a ex:Person ; rdfs:label "Alice" ; ex:age 39 ; ex:knows ex:bob, ex:carol ; ex:worksFor ex:acme .
ex:bob a ex:Person ; rdfs:label "Bob" ; ex:worksFor ex:acme ; ex:knows ex:dave .
ex:carol a ex:Person ; rdfs:label "Carol" ; ex:worksFor ex:globex ; ex:livesIn ex:bergen .
ex:dave a ex:Person ; rdfs:label "Dave" ; ex:worksFor ex:globex ; ex:knows ex:erin .
ex:erin a ex:Person ; rdfs:label "Erin" ; ex:livesIn ex:oslo .
ex:frank a ex:Person ; rdfs:label "Frank" ; ex:knows ex:alice .
ex:acme a ex:Organization ; rdfs:label "Acme" ; ex:location ex:oslo ; ex:partner ex:globex ; ex:makes ex:anvil, ex:rocket .
ex:anvil rdfs:label "Anvil" .
ex:rocket rdfs:label "Rocket" .
ex:globex a ex:Organization ; rdfs:label "Globex" ; ex:location ex:bergen .
ex:oslo a ex:City ; rdfs:label "Oslo" .
ex:bergen a ex:City ; rdfs:label "Bergen" .
`;

function largeData() {
    const lines = ['@prefix ex: <http://example.org/consistency-large/> .',
        '@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .',
        'ex:hub rdfs:label "Hub" .'];
    for (let i = 1; i < LARGE_NODES; i++) lines.push(`ex:hub ex:has ex:n${i} . ex:n${i} rdfs:label "Node ${i}" .`);
    return lines.join('\n');
}

async function createRepository(request, repositoryId, label, data) {
    const repositoryUrl = `${serverBaseUrl()}/repositories/${repositoryId}`;
    const created = await request.put(repositoryUrl, {
        headers: { 'Content-Type': 'text/turtle' },
        data: memoryRepositoryConfiguration(repositoryId, label)
    });
    expect([200, 201, 204]).toContain(created.status());
    const loaded = await request.post(`${repositoryUrl}/statements`, {
        headers: { 'Content-Type': 'text/turtle' },
        data
    });
    expect([200, 204]).toContain(loaded.status());
}

test.beforeAll(async ({ request }) => {
    await createRepository(request, REPOSITORY_ID, 'Graph consistency', DATA);
    await createRepository(request, LARGE_REPOSITORY_ID, 'Graph consistency (large)', largeData());
});

test.afterAll(async ({ request }) => {
    await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
    await deleteRepository(request, serverBaseUrl(), LARGE_REPOSITORY_ID);
});

const explorerOf = (page) => page.locator('.graph-explorer');
const node = (page, label) => explorerOf(page).locator('.graph-node')
    .filter({ has: page.locator('text', { hasText: new RegExp(`^${label}$`) }) }).first();
const canvas = (page) => explorerOf(page).locator('svg.graph-canvas');
const summary = (page) => explorerOf(page).locator('.selection-summary strong');
const nodeCard = (page) => explorerOf(page).locator('.node-details');

async function openGraph(page) {
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.goto(repositoryPageUrl(REPOSITORY_ID, 'graph'));
    await waitForRoute(page, 'graph');
    const explorer = explorerOf(page);
    await explorer.getByRole('button', { name: 'Load 100 statements' }).click();
    await expect(node(page, 'Oslo')).toBeAttached({ timeout: 30000 });
    await page.waitForTimeout(1500); // the layout settles
    return explorer;
}

/** Graph-coordinate transforms of every drawn node, by label. */
function nodePositions(page) {
    return page.evaluate(() => Object.fromEntries([...document.querySelectorAll('.graph-explorer .graph-node')]
        .map((element) => [element.querySelector('text')?.textContent, element.getAttribute('transform')])));
}

/** A point on the canvas with nothing under it for a few pixels around. */
async function emptyCanvasPoint(page) {
    const point = await canvas(page).evaluate((svg) => {
        const rect = svg.getBoundingClientRect();
        for (let y = rect.top + 60; y < rect.bottom - 60; y += 23) {
            for (let x = rect.left + 60; x < rect.right - 60; x += 23) {
                const around = [[0, 0], [-14, 0], [14, 0], [0, -14], [0, 14]];
                if (around.every(([dx, dy]) => document.elementFromPoint(x + dx, y + dy) === svg)) return { x, y };
            }
        }
        return null;
    });
    expect(point).not.toBeNull();
    return point;
}

async function opacityOf(locator) {
    return locator.evaluate((element) => Number(getComputedStyle(element).opacity));
}

test('Escape closes the card with the highlight it explains, then clears the selection', async ({ page }) => {
    await openGraph(page);
    await node(page, 'Alice').click();
    await expect(nodeCard(page).locator('h3')).toHaveText('Alice');
    await expect(canvas(page)).toHaveClass(/dim-by-focus/);
    await page.keyboard.press('Escape');
    await expect(nodeCard(page)).toHaveCount(0);
    // The pointer still over Alice highlights her neighbourhood as any hover does; away from her, nothing is.
    const empty = await emptyCanvasPoint(page);
    await page.mouse.move(empty.x, empty.y);
    await expect(canvas(page)).not.toHaveClass(/dim-by-focus/);

    await node(page, 'Bob').click({ modifiers: ['Shift'] });
    await node(page, 'Carol').click({ modifiers: ['Shift'] });
    await expect(summary(page)).toHaveText('2 nodes selected');
    await page.keyboard.press('Escape');
    await expect(summary(page)).toHaveCount(0);
    await expect(explorerOf(page).locator('.graph-node.is-selected')).toHaveCount(0);
});

