test('scrolling while a layout runs does not stop it halfway', async ({ page }) => {
    const explorer = await openGraph(page);
    const layout = explorer.locator('details', { has: page.locator('summary[aria-label="Choose graph layout"]') });
    // The square layout without interruption, then undone.
    await layout.locator('summary').click();
    await layout.getByRole('button', { name: 'Square' }).click();
    await expect(explorer.locator('.status-text')).toHaveText(/^Arranged/, { timeout: 15000 });
    await page.waitForTimeout(1200);
    const square = await nodePositions(page);
    await page.keyboard.press('ControlOrMeta+z');
    await page.waitForTimeout(1200);
    expect(await nodePositions(page)).not.toEqual(square);

    // The same layout with a scroll while its nodes move into place.
    const box = await canvas(page).boundingBox();
    await page.mouse.move(box.x + 40, box.y + box.height - 40);
    await layout.locator('summary').click();
    await layout.getByRole('button', { name: 'Square' }).click();
    await expect(explorer.locator('.status-text')).toHaveText(/^Arranged/, { timeout: 15000 });
    await page.mouse.wheel(0, 120);
    await page.waitForTimeout(1200);
    expect(await nodePositions(page)).toEqual(square);
});

