test.describe('the large renderer', () => {
    async function openLarge(page) {
        await page.setViewportSize({ width: 1440, height: 900 });
        await page.goto(repositoryPageUrl(LARGE_REPOSITORY_ID, 'graph'));
        await waitForRoute(page, 'graph');
        const explorer = explorerOf(page);
        await explorer.getByRole('button', { name: 'Query editor', exact: true }).click();
        await explorer.locator('#sparql').fill(
            'CONSTRUCT { ?s ?p ?o } WHERE { ?s ?p ?o FILTER(?p != <http://www.w3.org/2000/01/rdf-schema#label>) }');
        await explorer.getByRole('button', { name: 'Run query' }).click();
        await expect(explorer.getByRole('button', { name: 'Run query' })).toBeEnabled({ timeout: 30000 });
        await explorer.getByRole('button', { name: 'Close query editor' }).click();
        await expect(explorer.locator('canvas.large-graph-interactive')).toBeVisible({ timeout: 30000 });
        await expect(explorer.locator('.large-graph-hint')).not.toContainText('Arranging', { timeout: 30000 });
        await page.waitForTimeout(1000);
        return explorer;
    }

    async function find(page, text) {
        await page.keyboard.press('/');
        await expect(explorerOf(page).getByRole('combobox', { name: /^Find/ })).toBeFocused();
        await page.keyboard.press('ControlOrMeta+a');
        await page.keyboard.type(text);
        await expect(explorerOf(page).getByRole('option').first()).toContainText(text, { timeout: 15000 });
        await page.keyboard.press('Enter');
        await expect(nodeCard(page).locator('h3')).toHaveText(text);
    }

    test('Command+A selects every drawn node in the WebGL canvas', async ({ page }) => {
        const explorer = await openLarge(page);
        const interactive = explorer.locator('canvas.large-graph-interactive');
        const nodeCount = Number((await explorer.locator('.graph-stats').textContent()).match(/^\d+/)[0]);
        await expect(interactive).toHaveAttribute('data-renderer', 'webgl');
        await interactive.focus();
        await page.keyboard.press('Meta+a');
        await expect(summary(page)).toHaveText(`${nodeCount} nodes selected`);
        await expect(interactive).toHaveAttribute('aria-label', /⌘A selects all drawn nodes|Ctrl\+A selects all drawn nodes/);
    });

    test('Enter on the canvas shows the details of its node, as on the small canvas', async ({ page }) => {
        const explorer = await openLarge(page);
        await find(page, 'Node 7');
        await explorer.locator('canvas.large-graph-interactive').focus();
        await page.keyboard.press('Enter');
        await expect(explorer.getByRole('dialog', { name: /^Actions for/ })).toHaveCount(0);
        await expect(nodeCard(page).locator('h3')).toHaveText('Node 7');
    });

    test('arrow keys move from the shown node, or start from the middle of the view', async ({ page }) => {
        const explorer = await openLarge(page);
        const interactive = explorer.locator('canvas.large-graph-interactive');
        await interactive.focus();
        await page.keyboard.press('ArrowDown');
        const title = nodeCard(page).locator('h3');
        await expect(title).toBeVisible();
        const first = await title.textContent();
        await page.keyboard.press('ArrowRight');
        await expect(title).not.toHaveText(first);
    });

    test('Escape closes the card first and keeps the selection, as on the small canvas', async ({ page }) => {
        const explorer = await openLarge(page);
        await find(page, 'Node 7');
        const interactive = explorer.locator('canvas.large-graph-interactive');
        await interactive.focus();
        await page.keyboard.press('Shift+F10');
        const menu = explorer.getByRole('dialog', { name: 'Actions for Node 7' });
        await expect(menu).toBeVisible();
        await menu.getByRole('button', { name: 'Select neighbours' }).click();
        await expect(summary(page)).toHaveText('1 node selected');
        await find(page, 'Node 8');
        await interactive.focus();
        await page.keyboard.press('Escape');
        await expect(nodeCard(page)).toHaveCount(0);
        await expect(summary(page)).toHaveText('1 node selected');
        await page.keyboard.press('Escape');
        await expect(summary(page)).toHaveCount(0);
    });
});
